// ====================================================================
// ⚙️ PANEL DE CONFIGURACIÓN CENTRAL - MUNICIPALIDAD DE LA PLATA
// ====================================================================
// Cualquier persona sin conocimientos técnicos puede personalizar el municipio
// cambiando únicamente estos valores en 60 segundos:
const CONFIG_MUNICIPIO = {
  nombre_municipio: "Municipalidad de La Plata",
  provincia_region: "Buenos Aires, Argentina",
  eslogan: "Ciudad Capital - Gestión Abierta y Cercana 24/7",
  portal_web: "https://laplata.gob.ar",
  portal_tramites: "https://tramites.laplata.gob.ar",
  portal_rentas_pagos: "https://apr.laplata.gob.ar",
  portal_juzgado_multas: "https://faltas.laplata.gob.ar",
  portal_turismo: "https://turismo.laplata.gob.ar",
  telefono_atencion_vecinal: "147",
  telefono_emergencias_salud: "107",
  telefono_defensa_civil: "103",
  telefono_seguridad_urbana: "911",
  google_drive_folder_id: "15RAFPM8n1VbhjlC2f8MaEuNLCp2ZZqvv",
  google_drive_folder_url: "https://drive.google.com/drive/folders/15RAFPM8n1VbhjlC2f8MaEuNLCp2ZZqvv?usp=drive_link",
  profile_picture_url: "https://files.catbox.moe/351dpp.jpg",
  redes_sociales: {
    instagram: "@laplataciudad",
    facebook: "/LaPlataCiudad",
    x_twitter: "@LaPlataCiudad"
  },
  fuente_conocimiento_notebooklm: "Base Oficial de Normativas y Guía de Trámites La Plata 2026"
};

const rawIncoming = $node["Webhook POST (Mensajes Web Chat)"] ? $node["Webhook POST (Mensajes Web Chat)"].json : $input.first().json;
const payload = rawIncoming.body || rawIncoming;

const sessionId = payload.sessionId || payload.userId || 'web-session-' + Date.now();
const userName = payload.userName || payload.name || 'Vecino/Visitante';
let messageType = payload.messageType || (payload.audioBase64 ? 'audio' : 'text');
let messageText = payload.message || payload.text || '';
let audioBase64 = payload.audioBase64 || '';
let userPreference = payload.userPreference || 'auto'; // 'auto', 'text', 'voice'

const cleanText = messageText.trim().toLowerCase();
let action = payload.action || 'process_query';

if (cleanText === 'hola' || cleanText === 'inicio' || cleanText === 'menu' || cleanText === 'empezar' || cleanText === 'comenzar' || cleanText === 'buenas' || action === 'send_welcome') {
  action = 'send_welcome';
} else if (cleanText.includes('btn_mode_text') || cleanText.includes('seguir con msj') || cleanText.includes('solo texto') || cleanText === '1' || cleanText === 'modo texto' || cleanText === 'texto' || cleanText.includes('prefiero texto')) {
  action = 'set_pref_text';
  userPreference = 'text';
} else if (cleanText.includes('btn_mode_voice') || cleanText.includes('seguir por voz') || cleanText.includes('nota de voz') || cleanText.includes('audio') || cleanText === '2' || cleanText === 'modo voz' || cleanText === 'voz' || cleanText.includes('prefiero audio')) {
  action = 'set_pref_voice';
  userPreference = 'voice';
} else if (cleanText.includes('cambiar modo') || cleanText.includes('cambiar preferencia')) {
  action = 'send_welcome';
}

const spokenWelcome = `¡Hola, ${userName}! Te damos la bienvenida al Asistente Virtual Oficial de la ${CONFIG_MUNICIPIO.nombre_municipio}. Estoy aquí para resolver tus dudas las 24 horas sobre trámites, licencias de conducir, tasas de APR, multas de tránsito, turismo o normativas. ¿Cómo prefieres que nos comuniquemos hoy? Puedes elegir seguir con mensaje escrito o seguir por voz con los botones en pantalla.`;

return {
  json: {
    config: CONFIG_MUNICIPIO,
    sessionId,
    userName,
    messageType,
    messageText,
    cleanText,
    audioBase64,
    action,
    userPreference,
    spokenWelcome,
    timestamp: new Date().toISOString()
  }
};

const item = $input.first().json;
let rawBase64 = item.audioBase64 || '';
let originalHeader = '';

if (rawBase64.includes(',')) {
  const parts = rawBase64.split(',');
  originalHeader = parts[0];
  rawBase64 = parts[1];
}

let ext = 'webm';
let mime = 'audio/webm';
if (originalHeader.includes('audio/ogg') || originalHeader.includes('ogg')) {
  ext = 'ogg';
  mime = 'audio/ogg';
} else if (originalHeader.includes('audio/mp4') || originalHeader.includes('mp4')) {
  ext = 'mp4';
  mime = 'audio/mp4';
} else if (originalHeader.includes('audio/wav') || originalHeader.includes('wav')) {
  ext = 'wav';
  mime = 'audio/wav';
} else if (originalHeader.includes('audio/mp3') || originalHeader.includes('mp3') || originalHeader.includes('mpeg')) {
  ext = 'mp3';
  mime = 'audio/mp3';
}

return {
  json: {
    ...item,
    audioExt: ext,
    audioMime: mime
  },
  binary: {
    data: {
      data: rawBase64,
      mimeType: mime,
      fileName: `voice_input.${ext}`,
      fileExtension: ext
    }
  }
};

const item = $input.first().json;
const audioTranscription = (item.text || item.message || '').trim();
const originalData = $node["⚙️ Configuración & Parser Web"].json;

let messageText = audioTranscription;
let cleanText = audioTranscription.toLowerCase();

if (!cleanText || cleanText.length === 0 || item.error) {
  messageText = 'Mensaje de voz recibido. ¿Cómo puedo ayudarte?';
  cleanText = 'hola';
}

return {
  json: {
    ...originalData,
    messageText: messageText,
    cleanText: cleanText,
    audioTranscribed: true,
    userPreference: 'voice'
  }
};

const item = $input.first().json;
const cfg = item.config || {};

const welcomeText = `🏛️ **¡Hola, ${item.userName || 'Vecino/a'}! Te damos la bienvenida al Asistente Virtual Oficial de la ${cfg.nombre_municipio || 'Municipalidad de La Plata'}.**\n*${cfg.eslogan || 'Ciudad Capital - Gestión 24/7'}*\n\nEstoy aquí para resolver tus dudas las 24 horas sobre trámites, servicios y turismo:\n\n• 🚗 **Trámites & Licencias de Conducir (Turnos)**\n• 💳 **Tasas Municipales, Deudas y Pagos en APR**\n• ⚖️ **Multas de Tránsito y Descargos**\n• 🛠️ **Reclamos y Cuadrillas Urbanas 147**\n• 🌲 **Turismo, Cultura y Secretos de la Ciudad**\n• 📂 **Normativas y Base Documental**\n\n¿Cómo prefieres comunicarte hoy? Puedes elegir una de las siguientes opciones:`;

const quickReplies = [
  { id: 'btn_mode_text', title: 'Seguir con msj 📝', payload: 'btn_mode_text' },
  { id: 'btn_mode_voice', title: 'Seguir por voz 🎙️', payload: 'btn_mode_voice' },
  { id: 'btn_licencias', title: '🚗 Licencia de Conducir', payload: '¿Cómo renuevo mi licencia de conducir?' },
  { id: 'btn_tasas', title: '💳 Consultar Tasas APR', payload: '¿Dónde pago mis tasas municipales de APR?' },
  { id: 'btn_turismo', title: '🌲 Guía Turística & Secretos', payload: '¿Qué lugares históricos y secretos tiene la ciudad?' }
];

return {
  json: {
    ...item,
    responseText: welcomeText,
    spokenText: item.spokenWelcome || '¡Hola! Te damos la bienvenida al Asistente Virtual Oficial de la Municipalidad de La Plata. ¿Cómo prefieres comunicarte hoy? Elige seguir con mensaje o seguir por voz.',
    outputMode: item.userPreference === 'voice' ? 'voice' : 'text',
    quickReplies: quickReplies
  }
};

const item = $input.first().json;
const ackText = `✅ **Perfecto. He configurado tus respuestas en modo TEXTO 📝.**\n\nA partir de este momento recibirás todas las explicaciones, requisitos y enlaces oficiales por escrito.\n\n¿En qué trámite, tasa de APR o consulta turística te puedo ayudar hoy?`;

const quickReplies = [
  { id: 'btn_licencia', title: '🚗 Turno Licencia', payload: 'Quiero un turno para licencia' },
  { id: 'btn_infraccion', title: '⚖️ Consultar Multas', payload: 'Consultar infracciones de tránsito' },
  { id: 'btn_tasas', title: '💳 Deuda Tasas APR', payload: 'Consultar deuda de tasas en APR' },
  { id: 'btn_reclamo', title: '🛠️ Reclamo 147', payload: 'Quiero registrar un reclamo' },
  { id: 'btn_turismo', title: '🗺️ Turismo y Paseos', payload: 'Recomiéndame paseos y restaurantes' }
];

return {
  json: {
    ...item,
    responseText: ackText,
    spokenText: 'Perfecto. He configurado tus respuestas en modo texto. A partir de este momento recibirás todas las respuestas por escrito. ¿En qué te puedo ayudar hoy?',
    outputMode: 'text',
    savedPreference: 'text',
    quickReplies: quickReplies
  }
};

const item = $input.first().json;
const ackText = `🎙️ **¡Excelente! He configurado tus respuestas en modo AUDIO / VOZ 🔊.**\n\nA partir de ahora te enviaré notas de voz con explicaciones claras, acompañadas de los enlaces oficiales debajo.\n\n¿Qué consulta deseas realizar? Puedes hablarle al micrófono o escribir.`;

const quickReplies = [
  { id: 'btn_licencia', title: '🚗 Turno Licencia', payload: 'Quiero un turno para licencia' },
  { id: 'btn_infraccion', title: '⚖️ Consultar Multas', payload: 'Consultar infracciones de tránsito' },
  { id: 'btn_tasas', title: '💳 Deuda Tasas APR', payload: 'Consultar deuda de tasas en APR' },
  { id: 'btn_reclamo', title: '🛠️ Reclamo 147', payload: 'Quiero registrar un reclamo' },
  { id: 'btn_turismo', title: '🗺️ Turismo y Paseos', payload: 'Recomiéndame paseos y restaurantes' }
];

return {
  json: {
    ...item,
    responseText: ackText,
    spokenText: '¡Excelente! He configurado tus respuestas en modo audio. A partir de ahora escucharás mis respuestas con voz natural, acompañadas de los enlaces oficiales por escrito. ¿Qué consulta deseas realizar?',
    outputMode: 'voice',
    savedPreference: 'voice',
    quickReplies: quickReplies
  }
};

// SIMULACIÓN REALISTA DE BASE DE DATOS APR (RENTAS LA PLATA)
const inputQuery = (typeof query === 'string' ? query : (query ? JSON.stringify(query) : '')).trim();
const portal_rentas_pagos = 'https://apr.laplata.gob.ar';

const cuitMatch = inputQuery.match(/[0-9]{2}-?[0-9]{8}-?[0-9]{1}/);
const dniMatch = inputQuery.match(/[0-9]{7,8}/);
const patenteMatch = inputQuery.match(/[A-Za-z]{2}\s?[0-9]{3}\s?[A-Za-z]{2}/) || inputQuery.match(/[A-Za-z]{3}\s?[0-9]{3}/);
const partidaMatch = inputQuery.match(/partida\s*[:#]?\s*([0-9]+)/i) || inputQuery.match(/lp-?[0-9]{4,8}/i);

if (!dniMatch && !cuitMatch && !patenteMatch && !partidaMatch) {
  return JSON.stringify({
    estado: 'DATOS_INSUFICIENTES',
    mensaje: 'Para consultar el padrón de APR de La Plata se requiere que el vecino proporcione su DNI, CUIT, Número de Partida Inmobiliaria o Patente del vehículo. Pídeselo amablemente al vecino antes de consultar.'
  });
}

const idStr = patenteMatch ? patenteMatch[0].toUpperCase().replace(/\s+/g, '') : (partidaMatch ? (partidaMatch[1] || partidaMatch[0]) : (cuitMatch ? cuitMatch[0] : dniMatch[0]));

const hashNum = idStr.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
const periodosAdeudados = (hashNum % 3) + 1;
const montoPorPeriodo = 4250 + ((hashNum % 5) * 850);
const totalSinDescuento = periodosAdeudados * montoPorPeriodo;
const descuentoBuenContribuyente = Math.round(totalSinDescuento * 0.15);
const totalConDescuento = totalSinDescuento - descuentoBuenContribuyente;
const codigoPagoElectronico = `APR-${idStr.replace(/[^A-Za-z0-9]/g, '')}-${Math.floor(1000 + Math.random() * 9000)}`;
const codigoBarras = `048${Math.floor(100000000000 + Math.random() * 900000000000)}`;

const resultadoAPR = {
  ente_recaudador: 'Agencia Platense de Recaudación (APR - Municipalidad de La Plata)',
  identificador_consultado: idStr,
  titular: 'Contribuyente Registrado en Padrón La Plata',
  tributo_consultado: (patenteMatch || inputQuery.toLowerCase().includes('patente') || inputQuery.toLowerCase().includes('auto')) ? 'Impuesto a los Automotores / Motovehículos' : 'Tasa por Servicios Urbanos Municipales (SUM)',
  estado_cuenta: 'Deuda Regularizable',
  detalle_periodos: [
    { cuota: 'Cuota 01/2026', vencimiento: '10/01/2026', importe: `$${montoPorPeriodo.toLocaleString('es-AR')}`, estado: 'Vencido' },
    ...(periodosAdeudados > 1 ? [{ cuota: 'Cuota 02/2026', vencimiento: '10/02/2026', importe: `$${montoPorPeriodo.toLocaleString('es-AR')}`, estado: 'Vencido' }] : []),
    ...(periodosAdeudados > 2 ? [{ cuota: 'Cuota 03/2026', vencimiento: '10/03/2026', importe: `$${montoPorPeriodo.toLocaleString('es-AR')}`, estado: 'Vencido' }] : [])
  ],
  total_liquidado: `$${totalSinDescuento.toLocaleString('es-AR')}`,
  beneficio_pago_contado_15off: `$${totalConDescuento.toLocaleString('es-AR')} (Ahorras $${descuentoBuenContribuyente.toLocaleString('es-AR')})`,
  codigo_pago_link_banelco: codigoPagoElectronico,
  codigo_barra_ventanilla: codigoBarras,
  medios_habilitados: 'Pago Online con Tarjeta de Débito/Crédito, QR interoperable (Mercado Pago, Cuenta DNI, BNA+), PagoFácil o RapiPago.',
  portal_pago_oficial: portal_rentas_pagos
};

return JSON.stringify(resultadoAPR);

// SIMULACIÓN REALISTA DE JUZGADO DE FALTAS DE LA PLATA
const inputQuery = (typeof query === 'string' ? query : (query ? JSON.stringify(query) : '')).trim();
const portal_juzgado_multas = 'https://faltas.laplata.gob.ar';

const patenteMatch = inputQuery.match(/[A-Za-z]{2}\s?[0-9]{3}\s?[A-Za-z]{2}/) || inputQuery.match(/[A-Za-z]{3}\s?[0-9]{3}/);
const dniMatch = inputQuery.match(/[0-9]{7,8}/);

if (!patenteMatch && !dniMatch) {
  return JSON.stringify({
    estado: 'DATOS_INSUFICIENTES',
    mensaje: 'Para consultar el registro oficial de infracciones del Juzgado de Faltas de La Plata se requiere la Patente/Dominio del vehículo (ej: AF123GH) o el número de DNI del titular. Por favor, solicita este dato al vecino antes de consultar el sistema.'
  });
}

const idStr = patenteMatch ? patenteMatch[0].toUpperCase().replace(/\s+/g, '') : dniMatch[0];
const numeroActa = `ACT-LP-${Math.floor(100000 + Math.random() * 900000)}`;
const valorOriginal = 38500;
const valorPagoVoluntario = valorOriginal * 0.5;

return JSON.stringify({
  juzgado: 'Juzgado de Faltas Municipal de La Plata (Sede Calle 48 entre 10 y 11)',
  identificador_consultado: idStr,
  estado: 'ACTA_PENDIENTE_DE_RESOLUCION',
  infracciones: [
    {
      acta_numero: numeroActa,
      fecha_infraccion: '15/01/2026 11:30 hs',
      ubicacion: 'Avenida 7 y Calle 54 (Centro, La Plata)',
      motivo: 'Exceso de velocidad / Inobservancia de señalización vial luminosa',
      monto_original: `$${valorOriginal.toLocaleString('es-AR')}`,
      monto_pago_voluntario_50off: `$${valorPagoVoluntario.toLocaleString('es-AR')} (Beneficio primeros 30 días)`,
      plazo_pago_voluntario: 'Vence en 15 días hábiles',
      codigo_pago_electronico: `FALTAS-${numeroActa}`
    }
  ],
  procedimiento_descargo: 'Puede presentar su descargo 100% online adjuntando documentación de prueba o solicitar audiencia con el Juez de Faltas.',
  portal_oficial_faltas: portal_juzgado_multas
});

// SIMULACIÓN REALISTA DE SISTEMA DE TURNOS MUNICIPALES LA PLATA
const inputQuery = (typeof query === 'string' ? query : (query ? JSON.stringify(query) : '')).trim();
const portal_tramites = 'https://tramites.laplata.gob.ar';

const dniMatch = inputQuery.match(/[0-9]{7,8}/);

if (!dniMatch) {
  return JSON.stringify({
    estado: 'DATOS_INSUFICIENTES',
    mensaje: 'Para agendar y reservar un turno oficial de Licencia de Conducir en La Plata se requiere obligatoriamente el número de DNI del titular. Por favor, solicítale el DNI al vecino antes de consultar.'
  });
}

const dni = dniMatch[0];

let sede = 'Sede Central de Licencias (Calle 20 y 50)';
if (inputQuery.toLowerCase().includes('hornos')) sede = 'Centro Comunal Los Hornos (Av. 66 y 143)';
if (inputQuery.toLowerCase().includes('city bell') || inputQuery.toLowerCase().includes('bell')) sede = 'Centro Comunal City Bell (Cantilo e/ 19 y 20)';
if (inputQuery.toLowerCase().includes('villa elvira')) sede = 'Centro Comunal Villa Elvira (Av. 7 y 82)';

let tramite = 'Renovación de Licencia de Conducir';
if (inputQuery.toLowerCase().includes('original') || inputQuery.toLowerCase().includes('primera vez')) tramite = 'Licencia Original (Primera Vez)';
if (inputQuery.toLowerCase().includes('duplicado')) tramite = 'Duplicado de Licencia por Pérdida/Robo';
if (inputQuery.toLowerCase().includes('ampliacion') || inputQuery.toLowerCase().includes('categoria')) tramite = 'Ampliación de Categoría de Licencia';

const fechaTurno = 'Miércoles 18 de Marzo de 2026';
const horaTurno = '09:30 hs';
const codigoTurno = `TUR-LP-2026-${Math.floor(10000 + Math.random() * 90000)}`;

return JSON.stringify({
  sistema: 'Sistema de Turnos y Autogestión Ciudadana La Plata',
  estado_reserva: 'CONFIRMADO_EXITOSO',
  codigo_turno: codigoTurno,
  tramite: tramite,
  titular_dni: dni,
  sede_asignada: sede,
  fecha_asignada: fechaTurno,
  horario_citacion: horaTurno,
  requisitos_obligatorios_a_presentar: [
    '1. DNI original con domicilio en la ciudad de La Plata (y fotocopia).',
    '2. Licencia de conducir anterior (en caso de renovación o ampliación).',
    '3. Boleta de pago del CENAT (Certificado Nacional de Antecedentes de Tránsito) abonada con 72 hs de anticipación.',
    '4. Libre deuda de infracciones de tránsito del Juzgado de Faltas.',
    '5. Concurrir con 15 minutos de anticipación con este código de turno.'
  ],
  mensaje_recordatorio: 'Si no puedes asistir, recuerda cancelar el turno con 24 hs de anticipación en el portal de turnos.',
  portal_turnos_oficial: portal_tramites + '/turnos'
});

// SIMULACIÓN REALISTA DE ATENCIÓN VECINAL Y RECLAMOS 147
const inputQuery = (typeof query === 'string' ? query : (query ? JSON.stringify(query) : '')).trim();
const portal_tramites = 'https://tramites.laplata.gob.ar';

const calleMatch = inputQuery.match(/calle\s*[0-9]+/i) || inputQuery.match(/diagonal\s*[0-9]+/i) || inputQuery.match(/av\.?\s*[0-9]+/i) || inputQuery.match(/[0-9]{1,3}\s*(y|e\/|entre|\/)\s*[0-9]{1,3}/i) || inputQuery.match(/calle\s+[a-zA-Z]+/i);

if (!calleMatch) {
  return JSON.stringify({
    estado: 'DATOS_INSUFICIENTES',
    mensaje: 'Para registrar un reclamo en la Línea 147 y derivar la cuadrilla municipal se precisa la ubicación exacta (ejemplo: Calle 7 e/ 50 y 51, o Diagonal 74 y 10). Por favor, solicita la dirección exacta o intersección al vecino antes de generar el ticket.'
  });
}

const ubicacion = calleMatch[0];

let rubro = 'Mantenimiento Urbano General';
let plazoResolucion = '48 a 72 hs hábiles';
if (inputQuery.toLowerCase().includes('luz') || inputQuery.toLowerCase().includes('luminaria') || inputQuery.toLowerCase().includes('farola') || inputQuery.toLowerCase().includes('foco')) {
  rubro = 'Alumbrado Público y Luminarias';
  plazoResolucion = '24 a 48 hs hábiles';
} else if (inputQuery.toLowerCase().includes('bache') || inputQuery.toLowerCase().includes('pozo') || inputQuery.toLowerCase().includes('asfalto')) {
  rubro = 'Bacheo y Mantenimiento de Vía Pública';
  plazoResolucion = '3 a 5 días hábiles';
} else if (inputQuery.toLowerCase().includes('poda') || inputQuery.toLowerCase().includes('arbol') || inputQuery.toLowerCase().includes('rama')) {
  rubro = 'Poda Correctiva y Despeje de Ramas';
  plazoResolucion = 'Cronograma semanal de cuadrilla comunal';
} else if (inputQuery.toLowerCase().includes('basura') || inputQuery.toLowerCase().includes('residuo') || inputQuery.toLowerCase().includes('reciclado')) {
  rubro = 'Higiene Urbana y Recolección No Habitual';
  plazoResolucion = '24 hs hábiles';
}

const ticketId = `REC-147-2026-${Math.floor(10000 + Math.random() * 90000)}`;

return JSON.stringify({
  sistema: 'Atención Ciudadana y Cuadrillas Urbanas 147 La Plata',
  estado: 'RECLAMO_REGISTRADO_EN_SISTEMA',
  numero_ticket_seguimiento: ticketId,
  categoria_servicio: rubro,
  ubicacion_registrada: ubicacion,
  tiempo_estimado_resolucion: plazoResolucion,
  estado_derivacion: 'Derivado automáticamente a la Delegación Comunal y Cuadrilla Técnica correspondiente',
  mensaje_al_vecino: `Tu reporte fue cargado con éxito. Guarda el número ${ticketId} para consultar el avance en cualquier momento.`,
  canal_seguimiento_online: portal_tramites + '/seguimiento-reclamos'
});

const query = ($input.first().json.query || $input.first().json.input || '').toLowerCase();
const google_drive_folder_url = 'https://drive.google.com/drive/folders/15RAFPM8n1VbhjlC2f8MaEuNLCp2ZZqvv?usp=drive_link';

const driveRepository = {
  carpeta_oficial_google_drive: google_drive_folder_url,
  folder_id: '15RAFPM8n1VbhjlC2f8MaEuNLCp2ZZqvv',
  documentos_destacados: [
    {
      nombre: 'Guia_Integral_Tramites_La_Plata_2026.pdf',
      descripcion: 'Detalle paso a paso de licencias, habilitaciones comerciales, exenciones y permisos de obra.',
      enlace: google_drive_folder_url
    },
    {
      nombre: 'Codigo_Tributario_APR_y_Calendario_Fiscal_2026.pdf',
      descripcion: 'Tabla de alícuotas, fechas de vencimiento de Tasa SUM y planes de moratoria de APR.',
      enlace: google_drive_folder_url
    },
    {
      nombre: 'Reglamento_Juzgado_Faltas_La_Plata.pdf',
      descripcion: 'Procedimiento formal de descargos, multas de tránsito y pago voluntario con 50% descuento.',
      enlace: google_drive_folder_url
    }
  ],
  mensaje: 'Toda la documentación oficial, resoluciones y ordenanzas se encuentran sincronizadas y disponibles en la carpeta compartida de Google Drive.'
};

return JSON.stringify(driveRepository);

// GUÍA TURÍSTICA, PATRIMONIO Y SECRETOS DE LA PLATA
const query = ($input.first().json.query || $input.first().json.input || '').toLowerCase();
const portal_turismo = 'https://turismo.laplata.gob.ar';

const turismoLaPlata = {
  atractivos_imperdibles: {
